-- Warcraft Reborn Mystic Enchants whose dummy effect stands for a proc that lived only in the tooltip: the rule
-- names what the dummy casts (one at random), the trigger amount as a percent of the hit (spread over its ticks),
-- or a chance per combo point the finishing move spends (spell_ascension_mystic_enchant_proc).
ALTER TABLE `coa_mystic_enchant_proc`
  ADD COLUMN `trigger_spells` VARCHAR(255) NOT NULL DEFAULT '' COMMENT 'what a dummy effect casts (one at random); empty = the effect trigger spell' AFTER `consume_aura`,
  ADD COLUMN `amount_pct` FLOAT NOT NULL DEFAULT 0 COMMENT 'trigger base points: percent of the hit, spread over its ticks' AFTER `trigger_spells`,
  ADD COLUMN `chance_per_combo` FLOAT NOT NULL DEFAULT 0 COMMENT 'chance per combo point spent (replaces chance)' AFTER `amount_pct`;

DELETE FROM `spell_proc` WHERE `SpellId` IN (1163070, 1180260, 1180610, 1567770, 1567772, 1569578, 1581729, 1585634, 1589486, 1691129);

DELETE FROM `spell_script_names` WHERE `spell_id` IN (1163070, 1180260, 1180610, 1567770, 1567772, 1569578, 1581729, 1585634, 1589486, 1691129) AND `ScriptName` = 'spell_ascension_mystic_enchant_proc';

DELETE FROM `coa_mystic_enchant_proc` WHERE `enchant_spell` IN (1163070, 1180260, 1180610, 1567770, 1567772, 1569578, 1581729, 1585634, 1589486, 1691129);
